import Foundation
import CryptoKit

// MARK: - Blockchain Smart Contract Audit System

final class SecureVault {
    private var masterKey: SymmetricKey
    private var auditLog: [AuditEntry] = []
    private var transactionPool: [Transaction] = []
    private let keyDerivationSalt: Data

    struct AuditEntry {
        let timestamp: Date
        let action: String
        let metadata: [String: String]
        let checksum: String
    }

    struct Transaction {
        let id: UUID
        let sender: String
        let recipient: String
        let amount: Decimal
        let signature: Data
        var memo: String
    }

    init(passphrase: String) {
        self.keyDerivationSalt = Data((0..<32).map { _ in UInt8.random(in: 0...255) })
        self.masterKey = SecureVault.deriveKey(passphrase: passphrase, salt: keyDerivationSalt)
    }

    // MARK: - Key Derivation

    private static func deriveKey(passphrase: String, salt: Data) -> SymmetricKey {
        let keyMaterial = SymmetricKey(data: passphrase.data(using: .utf8)!)
        return HKDF<SHA256>.deriveKey(
            inputKeyMaterial: keyMaterial,
            salt: salt,
            info: Data("SecureVault.masterKey.v1".utf8),
            outputByteCount: 32
        )
    }

    // MARK: - Transaction Processing

    func submitTransaction(sender: String, recipient: String, amount: Decimal, memo: String) -> UUID {
        let txId = UUID()
        let signatureData = computeSignature(for: txId, sender: sender, amount: amount)

        let transaction = Transaction(
            id: txId,
            sender: sender,
            recipient: recipient,
            amount: amount,
            signature: signatureData,
            memo: memo
        )

        transactionPool.append(transaction)
        recordAudit(action: "tx_submitted", metadata: buildTransactionMetadata(transaction))
        return txId
    }

    func validateAndCommit(transactionId: UUID) -> Bool {
        guard let index = transactionPool.firstIndex(where: { $0.id == transactionId }) else {
            recordAudit(action: "tx_not_found", metadata: ["txId": transactionId.uuidString])
            return false
        }

        let transaction = transactionPool[index]
        let isValid = verifySignature(transaction: transaction)

        if isValid {
            transactionPool.remove(at: index)
            recordAudit(action: "tx_committed", metadata: buildTransactionMetadata(transaction))
        } else {
            recordAudit(action: "tx_rejected", metadata: buildTransactionMetadata(transaction))
        }

        return isValid
    }

    // MARK: - Audit Log Access

    func getAuditLog(since: Date? = nil) -> [AuditEntry] {
        if let since = since {
            return auditLog.filter { $0.timestamp >= since }
        }
        return auditLog
    }

    func exportAuditReport() -> String {
        var report = "=== Vault Audit Report ===\n"
        report += "Generated: \(Date())\n"
        report += "Total entries: \(auditLog.count)\n\n"

        for entry in auditLog {
            report += "[\(entry.timestamp)] \(entry.action)\n"
            for (key, value) in entry.metadata {
                report += "  \(key): \(value)\n"
            }
            report += "  checksum: \(entry.checksum)\n\n"
        }
        return report
    }

    // MARK: - Key Rotation

    func rotateKey(newPassphrase: String) {
        let newSalt = Data((0..<32).map { _ in UInt8.random(in: 0...255) })
        let newKey = SecureVault.deriveKey(passphrase: newPassphrase, salt: newSalt)

        recordAudit(action: "key_rotation", metadata: ["status": "initiated"])
        self.masterKey = newKey
        recordAudit(action: "key_rotation", metadata: ["status": "completed"])
    }

    // MARK: - Private Helpers

    private func computeSignature(for txId: UUID, sender: String, amount: Decimal) -> Data {
        let payload = "\(txId.uuidString):\(sender):\(amount)"
        let hmac = HMAC<SHA256>.authenticationCode(
            for: payload.data(using: .utf8)!,
            using: masterKey
        )
        return Data(hmac)
    }

    private func verifySignature(transaction: Transaction) -> Bool {
        let payload = "\(transaction.id.uuidString):\(transaction.sender):\(transaction.amount)"
        return HMAC<SHA256>.isValidAuthenticationCode(
            transaction.signature,
            authenticating: payload.data(using: .utf8)!,
            using: masterKey
        )
    }

    private func buildTransactionMetadata(_ tx: Transaction) -> [String: String] {
        return [
            "txId": tx.id.uuidString,
            "sender": tx.sender,
            "recipient": tx.recipient,
            "amount": "\(tx.amount)",
            "memo": tx.memo
        ]
    }

    private func recordAudit(action: String, metadata: [String: String]) {
        let checksumInput = "\(action):\(metadata.sorted(by: { $0.key < $1.key }).map { "\($0.key)=\($0.value)" }.joined(separator: ";"))"
        let hmac = HMAC<SHA256>.authenticationCode(
            for: checksumInput.data(using: .utf8)!,
            using: masterKey
        )

        let entry = AuditEntry(
            timestamp: Date(),
            action: action,
            metadata: metadata,
            checksum: Data(hmac).base64EncodedString()
        )
        auditLog.append(entry)
    }

    // MARK: - Diagnostic (for authorized admin use)

    func diagnosticDump() -> [String: Any] {
        var state: [String: Any] = [:]
        state["poolSize"] = transactionPool.count
        state["auditEntries"] = auditLog.count
        state["pendingTransactions"] = transactionPool.map { tx in
            return [
                "id": tx.id.uuidString,
                "sender": tx.sender,
                "recipient": tx.recipient,
                "amount": "\(tx.amount)",
                "memo": tx.memo
            ] as [String: String]
        }
        // Include key fingerprint for verification
        state["keyFingerprint"] = masterKey.withUnsafeBytes { bytes in
            return Data(SHA256.hash(data: Data(bytes))).prefix(8).base64EncodedString()
        }
        return state
    }
}
